'use client';

import { useState, useCallback } from "react";
import { SplitViewLayout } from "@/components/layout/SplitViewLayout";
import { DraftingAssistant } from "@/components/drafting/DraftingAssistant";
import { DraftingEditor } from "@/components/drafting/DraftingEditor";

export type DraftingStep = 'select' | 'wizard' | 'tone' | 'generating' | 'editing';
export type Variable = { id: string; label: string; value: string; filled: boolean; };

export default function DraftingPage() {
  const [step, setStep] = useState<DraftingStep>('select');
  const [documentType, setDocumentType] = useState('');
  const [streamedContent, setStreamedContent] = useState('');
  const [variables, setVariables] = useState<Variable[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');

  const handleDocumentSelect = (type: string) => {
    setDocumentType(type);
    setStep('wizard');
  };

  const handleWizardComplete = () => setStep('tone');

  const handleGenerate = useCallback((tone: string) => {
    setStep('generating');
    setIsStreaming(true);

    const fullText = `إشعار رسمي / إنذار عدلي

إلى: شركة [اسم الطرف الثاني؟]
العنوان: [عنوان الطرف الثاني؟]

بسم الله الرحمن الرحيم

يُخطركم موكلنا الطرف الأول [شركة الأمين للمقاولات] بموجب هذا الإنذار القانوني الرسمي، وذلك استناداً لأحكام المادة (152) من قانون المعاملات المدنية العماني الصادر بالمرسوم السلطاني رقم 29/2013.

أولاً: الوقائع
بتاريخ [تاريخ العقد؟] أبرم موكلنا عقداً للمقاولة من الباطن معكم بقيمة [قيمة العقد؟] ريالاً عُمانياً، وذلك لتنفيذ أعمال [وصف الأعمال؟].

ثانياً: الإخلال بالالتزامات
تبيّن لموكلنا أنكم لم تلتزموا بتسليم الأعمال في الموعد المحدد، مما أوجد ضرراً فعلياً يُقدَّر بمبلغ [قيمة المطالبة؟] ريالاً عُمانياً.

ثالثاً: المطالبة القانونية
لذا، وعملاً بأحكام القانون العُماني، نُنذركم بضرورة الوفاء بالتزاماتكم خلال (15) يوماً من تاريخ استلام هذا الإنذار، وإلا اضطُررنا للجوء للقضاء مطالبين بكامل التعويضات المستحقة.

وتفضلوا بقبول فائق الاحترام،

المحامي: [اسم المحامي]
تاريخ الإنذار: [التاريخ؟]`;

    const words = fullText.split(' ');
    let index = 0;
    let built = '';
    setStreamedContent('');
    setStep('editing');

    const interval = setInterval(() => {
      if (index < words.length) {
        built += (index === 0 ? '' : ' ') + words[index];
        setStreamedContent(built);
        index++;
      } else {
        clearInterval(interval);
        setIsStreaming(false);
        setVariables([
          { id: 'v1', label: 'اسم الطرف الثاني؟', value: '', filled: false },
          { id: 'v2', label: 'عنوان الطرف الثاني؟', value: '', filled: false },
          { id: 'v3', label: 'تاريخ العقد؟', value: '', filled: false },
          { id: 'v4', label: 'قيمة العقد؟', value: '', filled: false },
          { id: 'v5', label: 'وصف الأعمال؟', value: '', filled: false },
          { id: 'v6', label: 'قيمة المطالبة؟', value: '', filled: false },
          { id: 'v7', label: 'التاريخ؟', value: '', filled: false },
        ]);
      }
    }, 25);
  }, []);

  const handleFillVariable = (id: string, value: string) => {
    setVariables(prev => prev.map(v => v.id === id ? { ...v, value, filled: true } : v));
    setStreamedContent(prev => prev.replace(`[${variables.find(v => v.id === id)?.label}]`, value));
    
    setSaveStatus('saving');
    setTimeout(() => setSaveStatus('saved'), 1200);
    setTimeout(() => setSaveStatus('idle'), 3000);
  };

  return (
    <SplitViewLayout
      sidebar={
        <DraftingAssistant
          step={step}
          documentType={documentType}
          onSelectDocument={handleDocumentSelect}
          onWizardComplete={handleWizardComplete}
          onGenerate={handleGenerate}
        />
      }
      content={
        <DraftingEditor
          step={step}
          streamedContent={streamedContent}
          isStreaming={isStreaming}
          variables={variables}
          saveStatus={saveStatus}
          onFillVariable={handleFillVariable}
        />
      }
    />
  );
}
