'use client';

import React, { useState } from 'react';
import { FileText, Gavel, Building2, Home, Scroll, UserMinus, ChevronRight, Sparkles, Search } from 'lucide-react';
import type { DraftingStep } from '@/app/drafting/page';

const documentTypes = [
  { id: 'notice', title: 'إنذار عدلي', desc: 'إخطار رسمي قانوني', icon: Gavel, color: 'bg-red-50 text-red-600' },
  { id: 'lawsuit', title: 'صحيفة دعوى', desc: 'رفع قضية أمام المحكمة', icon: Scroll, color: 'bg-purple-50 text-purple-600' },
  { id: 'contract', title: 'عقد مقاولة', desc: 'مقاولة من الباطن', icon: Building2, color: 'bg-blue-50 text-blue-600' },
  { id: 'lease', title: 'عقد إيجار', desc: 'إيجار تجاري أو سكني', icon: Home, color: 'bg-green-50 text-green-600' },
  { id: 'memo', title: 'مذكرة جوابية', desc: 'رد على مذكرة مقابلة', icon: FileText, color: 'bg-yellow-50 text-yellow-600' },
  { id: 'termination', title: 'خطاب إنهاء', desc: 'إنهاء عقد أو خدمات', icon: UserMinus, color: 'bg-orange-50 text-orange-600' },
];

const wizardSteps = [
  { id: 'basic', label: 'معلومات أساسية' },
  { id: 'parties', label: 'الأطراف' },
  { id: 'facts', label: 'الوقائع' },
  { id: 'verify', label: 'التحقق' },
  { id: 'generate', label: 'التوليد' },
];

const wizardQuestions = [
  { step: 0, question: 'ما هي المحكمة المختصة التي ستُودع فيها المستند؟', type: 'select', options: ['المحكمة التجارية', 'محكمة الاستئناف', 'المحكمة الابتدائية', 'المحكمة العمالية'] },
  { step: 1, question: 'من هو الطرف الأول (المُنذِر / صاحب الحق)؟', type: 'text', placeholder: 'الاسم الكامل أو اسم الشركة...' },
  { step: 2, question: 'ما هي الواقعة التي تستوجب هذا الإنذار؟ (اذكرها بإيجاز)', type: 'textarea', placeholder: 'مثال: أخلّ الطرف الثاني بالتزاماته التعاقدية بعدم تسليم المشروع في الموعد المحدد...' },
  { step: 3, question: 'ما هي قيمة المطالبة بالأرقام؟', type: 'number', placeholder: '0.000 OMR' },
];

interface DraftingAssistantProps {
  step: DraftingStep;
  documentType: string;
  onSelectDocument: (type: string) => void;
  onWizardComplete: () => void;
  onGenerate: (tone: string) => void;
}

export function DraftingAssistant({ step, documentType, onSelectDocument, onWizardComplete, onGenerate }: DraftingAssistantProps) {
  const [wizardIndex, setWizardIndex] = useState(0);
  const [answers, setAnswers] = useState<string[]>(Array(wizardQuestions.length).fill(''));
  const [currentAnswer, setCurrentAnswer] = useState('');
  const [selectedTone, setSelectedTone] = useState('firm');
  const [typeSearch, setTypeSearch] = useState('');

  const filteredTypes = documentTypes.filter(t =>
    t.title.includes(typeSearch) || t.desc.includes(typeSearch)
  );

  const handleNextWizard = () => {
    const updated = [...answers];
    updated[wizardIndex] = currentAnswer;
    setAnswers(updated);
    setCurrentAnswer('');
    if (wizardIndex < wizardQuestions.length - 1) {
      setWizardIndex(prev => prev + 1);
    } else {
      onWizardComplete();
    }
  };

  const progressPercent = ((wizardIndex) / wizardQuestions.length) * 100;

  // --- SELECT STEP ---
  if (step === 'select') {
    return (
      <div className="flex flex-col h-full bg-white">
        <div className="px-6 py-5 border-b border-gray-100">
          <div className="flex items-center gap-2 mb-4">
            <Sparkles className="w-5 h-5 text-blue-600" />
            <h2 className="font-semibold text-navy-900">كيف تبدأ مذكرتك اليوم؟</h2>
          </div>
          <div className="relative">
            <Search className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="ابحث عن نوع المستند..."
              value={typeSearch}
              onChange={e => setTypeSearch(e.target.value)}
              className="w-full pr-9 pl-4 py-2.5 text-sm border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 outline-none transition-all bg-gray-50"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-5">
          <div className="grid grid-cols-2 gap-3">
            {filteredTypes.map((doc, i) => (
              <button
                key={doc.id}
                onClick={() => onSelectDocument(doc.id)}
                className="flex flex-col items-start p-4 bg-white border border-gray-100 rounded-xl hover:border-blue-200 hover:shadow-md transition-all duration-200 text-right animate-slide-up group"
                style={{ animationDelay: `${i * 50}ms` }}
              >
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center mb-3 ${doc.color} group-hover:scale-110 transition-transform`}>
                  <doc.icon className="w-5 h-5" />
                </div>
                <span className="font-semibold text-navy-900 text-sm group-hover:text-blue-600 transition-colors">{doc.title}</span>
                <span className="text-xs text-slate-500 mt-0.5">{doc.desc}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // --- WIZARD STEP ---
  if (step === 'wizard') {
    const q = wizardQuestions[wizardIndex];
    return (
      <div className="flex flex-col h-full bg-white">
        {/* Named Progress Bar */}
        <div className="px-6 pt-4 pb-2 border-b border-gray-100">
          <div className="flex justify-between mb-2">
            {wizardSteps.map((ws, i) => (
              <div key={ws.id} className="flex flex-col items-center gap-1">
                <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${
                  i < wizardIndex ? 'bg-blue-600 text-white' :
                  i === wizardIndex ? 'bg-blue-600 text-white ring-4 ring-blue-100' :
                  'bg-gray-100 text-gray-400'
                }`}>
                  {i < wizardIndex ? '✓' : i + 1}
                </div>
                <span className={`text-[9px] text-center ${i <= wizardIndex ? 'text-blue-600' : 'text-slate-400'}`}>
                  {ws.label}
                </span>
              </div>
            ))}
          </div>
          <div className="h-1 bg-gray-100 rounded-full mt-1 overflow-hidden">
            <div className="h-full bg-blue-600 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }} />
          </div>
          <p className="text-[10px] text-slate-400 mt-1 text-center">تبقى تقريباً {Math.max(1, (wizardQuestions.length - wizardIndex) * 1)} دقيقة لاكتمال المسودة</p>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {/* Previous answered questions (greyed out) */}
          {answers.slice(0, wizardIndex).map((ans, i) => ans && (
            <div key={i} className="mb-4 opacity-50">
              <div className="bg-slate-50 rounded-xl p-3 text-xs text-slate-500 border border-slate-100">
                {wizardQuestions[i].question}
              </div>
              <div className="mt-1 mr-4 bg-blue-600 text-white text-xs rounded-xl px-3 py-2 inline-block">
                {ans}
              </div>
            </div>
          ))}

          {/* Current question bubble */}
          <div className="animate-slide-up">
            <div className="flex items-start gap-3 mb-4">
              <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center flex-shrink-0">
                <Sparkles className="w-4 h-4 text-white" />
              </div>
              <div className="bg-gray-50 border border-gray-100 rounded-2xl rounded-tr-sm p-4 flex-1">
                <p className="text-sm text-navy-900 leading-relaxed">{q.question}</p>

                <div className="mt-3">
                  {q.type === 'text' && (
                    <input type="text" value={currentAnswer} onChange={e => setCurrentAnswer(e.target.value)}
                      placeholder={q.placeholder} onKeyDown={e => e.key === 'Enter' && currentAnswer && handleNextWizard()}
                      className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" />
                  )}
                  {q.type === 'textarea' && (
                    <textarea value={currentAnswer} onChange={e => setCurrentAnswer(e.target.value)}
                      placeholder={q.placeholder} rows={3}
                      className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all resize-none" />
                  )}
                  {q.type === 'select' && (
                    <select value={currentAnswer} onChange={e => setCurrentAnswer(e.target.value)}
                      className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all bg-white">
                      <option value="">اختر المحكمة...</option>
                      {q.options?.map(o => <option key={o} value={o}>{o}</option>)}
                    </select>
                  )}
                  {q.type === 'number' && (
                    <input type="text" value={currentAnswer} onChange={e => setCurrentAnswer(e.target.value)}
                      placeholder={q.placeholder}
                      className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" />
                  )}
                </div>
              </div>
            </div>

            <div className="flex items-center justify-between mr-11">
              <button onClick={() => { setCurrentAnswer('تم التخطي'); handleNextWizard(); }}
                className="text-xs text-slate-400 underline hover:text-slate-600 transition-colors">
                تخطي هذا السؤال
              </button>
              <button onClick={handleNextWizard} disabled={!currentAnswer}
                className="flex items-center gap-2 bg-blue-600 disabled:bg-blue-300 text-white text-sm px-4 py-2 rounded-lg transition-colors hover:bg-blue-700">
                {wizardIndex < wizardQuestions.length - 1 ? 'التالي' : 'متابعة'}
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // --- TONE STEP ---
  if (step === 'tone') {
    const tones = [
      { id: 'firm', label: 'حازم ومباشر', desc: 'مناسب للإنذارات والمطالبات القضائية' },
      { id: 'friendly', label: 'ودي / تسوية', desc: 'مناسب للتفاوض وإنهاء النزاعات وديًا' },
      { id: 'detailed', label: 'أكاديمي / مفصّل', desc: 'مشبع بالأسانيد والمراجع القانونية' },
    ];
    return (
      <div className="flex flex-col h-full bg-white">
        <div className="px-6 py-4 border-b border-gray-100">
          <h2 className="font-semibold text-navy-900">اختر أسلوب المستند</h2>
          <p className="text-xs text-slate-500 mt-1">سيُكيّف الذكاء الاصطناعي صياغته وفقاً للأسلوب المختار</p>
        </div>

        <div className="flex-1 p-6 space-y-3">
          {tones.map(t => (
            <button key={t.id} onClick={() => setSelectedTone(t.id)}
              className={`w-full text-right p-4 rounded-xl border-2 transition-all ${
                selectedTone === t.id ? 'border-blue-500 bg-blue-50' : 'border-gray-100 hover:border-gray-200 bg-white'
              }`}>
              <div className="flex items-center gap-3">
                <div className={`w-4 h-4 rounded-full border-2 flex-shrink-0 ${
                  selectedTone === t.id ? 'border-blue-500 bg-blue-500' : 'border-gray-300'
                }`} />
                <div>
                  <p className="font-semibold text-sm text-navy-900">{t.label}</p>
                  <p className="text-xs text-slate-500 mt-0.5">{t.desc}</p>
                </div>
              </div>
            </button>
          ))}

          <div className="pt-4 border-t border-gray-100 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-sm text-navy-900">اللغة</span>
              <div className="flex gap-2">
                {['عربية فصحى', 'قانونية دقيقة'].map(l => (
                  <button key={l} className="text-xs border border-blue-200 bg-blue-50 text-blue-700 px-3 py-1 rounded-full">
                    {l}
                  </button>
                ))}
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-navy-900">حجم المستند</span>
              <div className="flex gap-2">
                {['مختصر', 'متوسط', 'مفصّل'].map((s, i) => (
                  <button key={s} className={`text-xs border px-3 py-1 rounded-full transition-colors ${
                    i === 1 ? 'border-blue-500 bg-blue-600 text-white' : 'border-gray-200 text-gray-600'
                  }`}>{s}</button>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="p-6 border-t border-gray-100">
          <button onClick={() => onGenerate(selectedTone)}
            className="w-full flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-4 rounded-xl transition-colors shadow-sm shadow-blue-200">
            <Sparkles className="w-5 h-5" />
            توليد المسودة الآن
          </button>
        </div>
      </div>
    );
  }

  // --- EDITING STEP ---
  if (step === 'editing' || step === 'generating') {
    return (
      <div className="flex flex-col h-full bg-white">
        <div className="px-6 py-4 border-b border-gray-100">
          <div className="flex items-center gap-2">
            <Sparkles className="w-4 h-4 text-blue-600 animate-pulse" />
            <h2 className="font-semibold text-navy-900 text-sm">
              {step === 'generating' ? 'جاري كتابة المسودة...' : 'المسودة جاهزة للمراجعة'}
            </h2>
          </div>
          {step === 'editing' && (
            <p className="text-xs text-slate-500 mt-1">يمكنك التعديل في المحرر مباشرة أو طرح استفسار هنا</p>
          )}
        </div>
        <div className="flex-1 flex items-center justify-center text-slate-400 text-sm p-6 text-center">
          {step === 'generating' ? (
            <div className="flex flex-col items-center gap-3">
              <div className="w-10 h-10 rounded-full border-2 border-blue-500 border-t-transparent animate-spin" />
              <span>يكتب الذكاء الاصطناعي مسودتك...</span>
            </div>
          ) : (
            <p className="leading-relaxed">المسودة جاهزة! راجعها في المحرر الأيسر، وانقر على المتغيرات البرتقالية لتعبئتها، أو اسألني لتعديل أي فقرة.</p>
          )}
        </div>
      </div>
    );
  }

  return null;
}
